-- Name: vw_comparativo_rag; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_comparativo_rag AS
 SELECT r3.id_membro,
    mem.nome AS nome_membro,
    r3.id_pergunta_original,
    r3.modelo,
    a2.nota_juiz AS nota_sem_rag,
    a3.nota_juiz AS nota_com_rag,
    (a3.nota_juiz - a2.nota_juiz) AS evolucao_nota,
    a3.chain_of_thought AS analise_do_juiz_sobre_o_rag
   FROM (((public.atividade3_respostas_rag r3
     JOIN public.membros mem ON ((mem.id_membro = r3.id_membro)))
     JOIN public.atividade3_avaliacoes_juiz a3 ON ((a3.id_resposta_rag = r3.id_resposta_rag)))
     LEFT JOIN public.atividade2_insights a2 ON (((a2.id_membro = r3.id_membro) AND ((a2.id_pergunta)::text = (r3.id_pergunta_original)::text) AND ((a2.modelo)::text = (r3.modelo)::text))));


ALTER VIEW public.vw_comparativo_rag OWNER TO postgres;

